mapper.select:
SELECT COUNT(*)
FROM media m
INNER JOIN media_visible mv ON m.id = mv.media_id AND mv.user_id = #{zoneUserId}
WHERE m.state = 0

    AND m.category = #{category}

SELECT m.id, m.uploader_id, m.file_hash, m.category, m.title, m.description,
       m.storage_path, m.cover_path, m.state, m.update_time
FROM media m
INNER JOIN media_visible mv ON m.id = mv.media_id AND mv.user_id = #{zoneUserId}
WHERE m.state = 0

    AND m.category = #{category}

ORDER BY m.update_time DESC, m.id DESC
LIMIT #{offset}, #{limit}
